from pathlib import Path
import json,hashlib,datetime
L=Path(__file__).resolve().parent; B=L.parent
utc=datetime.datetime.now(datetime.timezone.utc).isoformat()
def dump(p,x): (L/p).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def h(b):return hashlib.sha256(b).hexdigest()
notes={}
for s in (L/'technical-notes.tsv').read_text().splitlines():
 i,d,t=s.split('\t');assert int(i) not in notes;notes[int(i)]=(d,t)
primary={403680:('2022-22','Liebenau report, definition and Theorems 1-3, extracted lines 1049-1175'),403690:('2022-22','Problem Session Definition 1, Theorem 2, Problem 3, lines 2825-2842'),404026:('2023-1','rainbow matching report, Theorems 2-5 and conclusions, lines 2470-2580'),404027:('2023-1','rainbow matching report, Theorem 5 and explicit answer, lines 2535-2580'),404034:('2023-1','Problem Session Question 3 and Theorem 4, lines 3615-3635'),404231:('2023-36','Section 2, Theorem 2 and adjacent discussion, lines 3378-3420'),404387:('2023-9','Dietzel Sections 1-3, Definitions 1-2, Problems 9-10, lines 297-420'),404388:('2023-9','Van Antwerpen nilpotency report Problem 1 and context, lines 490-555'),404394:('2023-9','Stefanelli report, definitions, Theorem 1, Problems 2-5, lines 901-968')}
dis=[]
for x in json.loads((L/'records.json').read_text()):
 r=x['record'];i=r['mathdb_id'];d,t=notes[i];s=r['statement'];p=primary.get(i)
 dis.append({'mathdb_id':i,'title':r['title'],'literal_statement':s,'statement_utf8_sha256':h(s.encode()),'canonical_record_sha256':x['canonical_record_sha256'],'canonical_record_encoding':'UTF-8 JSON ensure_ascii=False sort_keys=True separators=(comma,colon)','original_chunk':x['original_chunk'],'original_line':x['original_line'],'canonical_url':r['canonical_url'],'source_url':r['source_url'],'disposition':d,'technical_disposition':t,'record_statement_review':'complete_literal_read','exact_quantifier_scope':'Exactly the literal statement above; all displayed universal/existential qualifiers retained, including corrupted control sequences. No domain repairs authorized.','primary_section_review':{'read':bool(p),'retained_file':('sources/'+p[0]+'.txt') if p else None,'scope':p[1] if p else 'Not inspected; source-scope gate remains HOLD; no claim that access was denied.'},'whole_primary_body_read':False,'proof_dependency_audit':'NOT performed; source theorem statements and local discussion only where indicated','closest_successor_review':('Retained rainbowc3.pdf Section 9.3 Propositions 9.4-9.5 and Question 10.4 read; upstream theorems and proof dependencies not audited; undated author-hosted version retrieved '+utc) if i==404034 else 'No closest successor body audited; HOLD if a surviving candidate is revisited. Source-internal exclusion does not require novelty clearance.','current_public_registry':'HOLD: no current registry head/chronology established; inherited denied AIProofWatch and forbidden GitHub routes not requested.','prior_cleared':False,'proof_evidence':'No new full proof or counterexample. Source-resolved exclusions rely on the indicated primary statement, not proof-body revalidation.','decisive_check_executed':('Read source Theorem 5 and its explicit conclusion; substitute t=3 for 404026 or fix integer t>beta and compare r log(t/beta) with O_t(sqrt(r))+log alpha_t for 404027.') if i in [404026,404027] else 'Full literal statement reviewed; primary section comparison only where recorded. No numerical sweep or formal check executed.','decisive_next_check_planned':'None authorized as investment by this packet. Reopen only after primary scope, closest successor, registry and substantive-credit gates are resolved.','certificate_size':'No new certificate produced or estimated; no surviving mechanism merits one.','formal_dependencies':'No Lean work. Any formal dependency inventory would be speculative before a surviving exact full-scope result.','strongest_objection':t,'source_scope_cleared':False,'mathematical_pass':False,'novelty_pass':False,'accepted_credit':0})
assert len(dis)==len(notes)==50
dump('dispositions.json',dis);dump('proposals.json',[])
# Flat provenance: no copies or recursion through bound JSON files.
urlmap={'2022-22':('https://ems.press/journals/owr/articles/10252930','https://ems.press/content/serial-article-files/46961','OWR 22/2022, published report'),'2023-1':('https://ems.press/journals/owr/articles/12697684','https://ems.press/content/serial-article-files/46994','OWR 1/2023, published report'),'2023-9':('https://ems.press/journals/owr/articles/12697693','https://ems.press/content/serial-article-files/47003','OWR 9/2023, published report'),'2023-36':('https://ems.press/journals/owr/articles/14297736','https://ems.press/content/serial-article-files/47475','OWR 36/2023, published report'),'rainbow':('https://web.math.princeton.edu/~nalon/PDFS/rainbowc3.pdf','https://web.math.princeton.edu/~nalon/PDFS/rainbowc3.pdf','Author-hosted rainbowc3 filename; body undated; precise journal-version equivalence not audited')}
sources=[]
for p in sorted((L/'sources').iterdir()):
 name=p.name.split('.')[0].replace('-pdf','');a,b,v=urlmap[name]
 sources.append({'file':str(p.relative_to(L)),'url':b if p.suffix in ['.pdf','.txt'] or '-pdf.' in p.name else a,'version':v,'retained_utc':utc,'utc_precision':'retention catalog completion; response Date retained in HTTP headers','http_status':200,'sha256':h(p.read_bytes()),'bytes':p.stat().st_size,'role':'pdftotext -layout derivative' if p.suffix=='.txt' else 'HTTP response headers' if p.suffix=='.headers' else 'primary source bytes','whole_body_reviewed':False})
