failures={'new_http_failures':[],'helper_failures':[],'zero_mathdb_requests':True,'inherited_holds':['MathDB 429: zero requests','AIM/Kourovka/EGRES parked','AIProofWatch denied: no retry','rigid-body and triangle-gap routes parked','GitHub API/raw/codeload/diff forbidden; no requests'],'scope_gaps':['41 of 50 cited primary question sections not inspected; these are source-scope HOLDs, not demonstrated hardness','0 whole primary bodies read','0 complete proof dependency audits','only 404034 has a closest-successor section read','current public registry heads and chronology NOT cleared'],'search':{'engine':'web search, not Google','utc':utc,'queries':['"additive dimension" "transpositions"','"skew braces" "prime-power order" construction 2024 2025'],'use':'Discovery leads only. rainbowc3 retained independently from author site. Search snippets not proof or novelty evidence.'}}
dump('failures.json',failures)
# Preserve initial flat binding list, extended with retained inputs only at this lane.
bs=json.loads((L/'bindings.json').read_text())
for p in [B.parents[4]/'AGENTS.md',B.parent/'AGENTS.md']:
 if p.exists() and str(p) not in {b['original'] for b in bs}:bs.append({'original':str(p),'sha256':h(p.read_bytes()),'bytes':p.stat().st_size})
dump('bindings.json',bs)
print('built',len(dis),'dispositions',len(primary),'primary sections',len(sources),'source artifacts')
